end=math.ceil(max(616.437551,align['duration'])*30)
chapters=[]
for i,(start,source,section,title,bullets,note) in enumerate(rows):
 stop=round(rows[i+1][0]*30) if i+1<len(rows) else end
 begin=round(start*30)
 c=dict(old[source]);c.update(code=f'N{i+1:02d}',section=section+1,kicker=align['sections'][section]['title'],title=title,bullets=bullets,note=note,start_frame=begin,end_frame=stop,duration_frames=stop-begin,duration=(stop-begin)/30)
 c.pop('source_type',None)
 if 'image' in c:
  assert Path(c['image']).is_file(),c['image']
  c['image']=os.path.relpath(c['image'],D)
 if 'sequence' in c:
  c['sequence']=dict(c['sequence']);c['sequence']['folder']=os.path.relpath(c['sequence']['folder'],D)
 chapters.append(c)
assert all(c['duration_frames']>0 for c in chapters)
assert sum(c['duration_frames'] for c in chapters)==end
(D/'NARRATED_CHAPTERS.json').write_text(json.dumps(chapters,ensure_ascii=False,indent=2)+'\n')
align.update(method='Local faster-whisper base, word timestamps, reference matching and reviewed section-start corrections',audio_sha256=hashlib.sha256((ROOT/'docs/management/recording.mp3').read_bytes()).hexdigest(),reference_sha256=hashlib.sha256((D/'NARRATION_CUES.md').read_bytes()).hexdigest(),render_duration_seconds=end/30)
(D/'NARRATION_ALIGNMENT.json').write_text(json.dumps(align,ensure_ascii=False,indent=2)+'\n')
with (D/'TIMING_NARRATED.csv').open('w',newline='') as f:
 w=csv.writer(f);w.writerow(['scene','section','start_seconds','end_seconds','title','status_note'])
 for c in chapters:w.writerow([c['code'],c['section'],f'{c["start_frame"]/30:.3f}',f'{c["end_frame"]/30:.3f}',c['title'].replace('\n',' '),c['note']])
print('Narrated plan:',len(chapters),'scenes,',end,'frames,',end/30,'seconds')
